import { posix } from 'node:path';
import type { CommandBrief } from '@puni/shared-command';
import { compareBytes } from './byte-order';
import type { ReadWhenEntry } from './index-sources';
import { placePage, wikiSections } from './wiki-sections';

/** The generated directory, relative to the repository root. */
export const indexDirectory = 'wiki/index';

/** The generated file to read first, relative to the repository root: it links every partition. */
export const indexFile = `${indexDirectory}/index.md`;

const notice = '<!-- Generated by `puni burokrat wiki index`. Do not edit. -->';

/** The generated file listing the projects and commands of `scope`. */
function partitionFile(scope: string): string {
  return `${indexDirectory}/${scope}.md`;
}

/** The words of a command's path: the program, then its role, then the rest. */
function splitPath(command: CommandBrief): readonly string[] {
  return command.path.split(' ');
}

function roleOf(command: CommandBrief): string | undefined {
  return splitPath(command)[1];
}

function listReadWhen(file: string, entries: readonly ReadWhenEntry[]): string[] {
  const directory = posix.dirname(file);
  return entries
    .map(
      (entry) => `- ${entry.readWhen}: [${entry.name}](${posix.relative(directory, entry.path)})`,
    )
    .sort(compareBytes);
}

function listCommandLines(commands: readonly CommandBrief[]): string[] {
  return [...commands]
    .sort((left, right) => compareBytes(left.path, right.path))
    .map((command) => `- \`${command.path}\`: ${command.brief}`);
}

/** A `## heading` and its lines, then a blank line; nothing when there are no lines. */
function renderSection(heading: string, lines: readonly string[], level = '##'): string[] {
  return lines.length === 0 ? [] : [`${level} ${heading}`, '', ...lines, ''];
}

/** `purpose` as a sentence: its first letter upper-case, ending in a full stop. */
function describe(purpose: string): string {
  return `${purpose.charAt(0).toUpperCase()}${purpose.slice(1)}.`;
}

/**
 * The index file's "Read when": the pages at the wiki root, then one `###` subsection per
 * {@link wikiSections} entry in its order, saying what its pages are for and listing them; a
 * section without pages is left out, and the whole is nothing when there are no pages.
 */
function renderPages(pages: readonly ReadWhenEntry[]): string[] {
  const inSection = (directory: string | undefined) =>
    pages.filter((page) => {
      const place = placePage(page.path);
      return place.kind === 'section'
        ? place.section.directory === directory
        : directory === undefined;
    });
  const subsections = wikiSections.flatMap(({ directory, heading, purpose }) => {
    const lines = listReadWhen(indexFile, inSection(directory));
    return renderSection(
      heading,
      lines.length === 0 ? [] : [describe(purpose), '', ...lines],
      '###',
    );
  });
  const root = listReadWhen(indexFile, inSection(undefined));
  if (root.length === 0 && subsections.length === 0) return [];
  return ['## Read when', '', ...(root.length === 0 ? [] : [...root, '']), ...subsections];
}

/** Every scope a project is tagged with or a role a command sits below, sorted bytewise. */
function listScopes(entries: readonly ReadWhenEntry[], commands: readonly CommandBrief[]) {
  const scopes = new Set<string>();
  for (const entry of entries) if (entry.scope !== undefined) scopes.add(entry.scope);
  for (const command of commands) {
    const role = roleOf(command);
    if (role !== undefined) scopes.add(role);
  }
  return [...scopes].sort(compareBytes);
}

/**
 * The full contents of `wiki/index/`, keyed by path relative to the repository root.
 * {@link indexFile} holds the pages, grouped by section (see `renderPages`), the role commands (the top of the tree) and one line per
 * partition; `wiki/index/<scope>.md`, one per scope a project is tagged with or a role a command
 * sits below, holds that scope's projects and the commands below its role. Lines are sorted
 * bytewise; a section with no lines is left out; the text has LF endings and carries no dates or
 * absolute paths.
 */
export function renderIndex(
  entries: readonly ReadWhenEntry[],
  commands: readonly CommandBrief[],
): Map<string, string> {
  const roleCommands = commands.filter((command) => splitPath(command).length === 2);
  const partitions = listScopes(entries, commands).map((scope) => {
    const file = partitionFile(scope);
    const role = roleCommands.find((command) => roleOf(command) === scope);
    const below = commands.filter(
      (command) => roleOf(command) === scope && splitPath(command).length > 2,
    );
    const projects = entries.filter((entry) => entry.scope === scope);
    const text = [
      notice,
      '',
      `# Wiki index: ${scope}`,
      '',
      ...renderSection('Read when', listReadWhen(file, projects)),
      ...renderSection('Commands', listCommandLines(below)),
    ].join('\n');
    const tagged = `the projects tagged \`scope:${scope}\``;
    const contents =
      role === undefined ? tagged : `${tagged} and the commands below \`${role.path}\``;
    return {
      file,
      text,
      line: `- [${scope}](${posix.relative(indexDirectory, file)}): ${contents}`,
    };
  });
  const pages = entries.filter((entry) => entry.scope === undefined);
  const index = [
    notice,
    '',
    '# Wiki index',
    '',
    ...renderPages(pages),
    ...renderSection('Commands', listCommandLines(roleCommands)),
    ...renderSection(
      'Partitions',
      partitions.map((partition) => partition.line),
    ),
  ].join('\n');
  return new Map([
    [indexFile, index],
    ...partitions.map((partition): [string, string] => [partition.file, partition.text]),
  ]);
}
